  --kerykeion-color-base-100: #0f172a;
  --kerykeion-color-info: #0ca5e9;
  --kerykeion-color-info-content: #000000;
  --kerykeion-color-success: #2dd4bf;
  --kerykeion-color-warning: #f4bf50;
  --kerykeion-color-error: #fb7085;

